const pairs = [
  { id: "kitchen", title: "Kitchen", before: "/work/kitchen-before.jpg", after: "/work/kitchen-after.jpg", alt: { before: "The kitchen with old tiles", after: "The same kitchen retiled in white" }, caption: "Retiled in four days." },
  { id: "hall", title: "Hallway", before: "/work/hall-before.jpg", after: "/work/hall-after.jpg", alt: { before: "A dark hallway", after: "The hallway painted and lit" } },
];
const [shown, setShown] = useState("kitchen");

<BeforeAfter
  heading="See the difference."
  intro="Drag the line on any of our recent jobs."
  pairs={pairs}
  pair={shown}
  onPairChange={(p) => setShown(p.id)}
  actions={{ primary: "Get a quote", secondary: "All projects", href: "/work" }}
  onPrimary={() => openQuote()}
/>
